def addition(a, b):
    return a + b

# Exemple : addition(2, 3) -> 5

def est_pair(n):
    return n % 2 == 0

# Exemple : est_pair(4) -> True, est_pair(7) -> False

def maximum(liste):
    plus_grand = liste[0]
    for x in liste:
        if x > plus_grand:
            plus_grand = x
    return plus_grand

# Exemple : maximum([3, 7, 2]) -> 7

def moyenne(liste):
    return sum(liste) / len(liste)

# Exemple : moyenne([2, 4, 6]) -> 4.0

def inverser(texte):
    return texte[::-1]

# Exemple : inverser('aura') -> 'arua'

def compter_voyelles(mot):
    return sum(1 for c in mot.lower() if c in 'aeiouy')

# Exemple : compter_voyelles('python') -> 2 ('o' et 'y')

def celsius_vers_fahrenheit(c):
    return c * 9 / 5 + 32

# Exemple : celsius_vers_fahrenheit(100) -> 212.0

def trier(liste):
    return sorted(liste)

# Exemple : trier([3, 1, 2]) -> [1, 2, 3]

def factorielle(n):
    resultat = 1
    for i in range(2, n + 1):
        resultat *= i
    return resultat

# Exemple : factorielle(5) -> 120

def somme(liste):
    total = 0
    for x in liste:
        total += x
    return total

# Exemple : somme([1, 2, 3]) -> 6

def longueur(texte):
    compteur = 0
    for _ in texte:
        compteur += 1
    return compteur

# Exemple : longueur('aura') -> 4

def km_vers_miles(km):
    return km * 0.621371

# Exemple : km_vers_miles(10) -> 6.21371

def signe(n):
    if n > 0:
        return 'positif'
    if n < 0:
        return 'negatif'
    return 'nul'

